begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','recorder_sessions','durable sessions exist');
select has_function('public','recorder_issue_ticket',array['uuid','uuid','uuid','boolean','text']);
select ok(not has_function_privilege('anon','recorder_issue_ticket(uuid,uuid,uuid,boolean,text)','execute'),'anon cannot start');
select ok(not has_function_privilege('authenticated','recorder_ingest(text,jsonb)','execute'),'browser cannot ingest');
select ok(has_function_privilege('service_role','recorder_ingest(text,jsonb)','execute'),'boundary can ingest');
select ok(not has_table_privilege('authenticated','recorder_tickets','select'),'ticket hashes private');
select ok(not has_table_privilege('service_role','recorder_sessions','insert'),'service only through contracts');
select ok((select relrowsecurity from pg_class where oid='recorder_sessions'::regclass),'session RLS');
select throws_ok($$select recorder_issue_ticket(gen_random_uuid(),gen_random_uuid(),null,true,'pilot-v1')$$,'42501','recorder_actor_denied','no actor denied');
select throws_ok($$select recorder_ingest('health','{}')$$,'42501','recorder_service_only','database owner without service claims denied');
create temporary table rf(name text primary key,id uuid,body jsonb);
grant all on rf to authenticated,service_role;
do $$ declare t uuid; b uuid; b2 uuid; d uuid; a uuid; u uuid; person text; begin
 insert into tenants(name,slug) values('Recorder fixture','recorder-fixture') returning id into t;
 insert into branches(tenant_id,name,code) values(t,'Capture','REC') returning id into b;
 insert into branches(tenant_id,name,code) values(t,'Other','REC2') returning id into b2;
 insert into departments(tenant_id,branch_id,name,code) values(t,b,'Capture','REC') returning id into d;
 insert into rf values('tenant',t,null),('branch',b,null),('branch2',b2,null),('device',gen_random_uuid(),null),('request',gen_random_uuid(),null);
 foreach person in array array['owner','ordinary','inactive','manager'] loop
  insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values(gen_random_uuid(),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',person||'-rec@test.local','x',now(),now()) returning id into a;
  insert into user_profiles(tenant_id,auth_user_id,branch_id,department_id,employee_name,employee_code,email,user_role,working_status,is_login_enabled,account_status)
   values(t,a,b,d,person,'REC-'||person,person||'-rec@test.local',case person when 'owner' then 'super_admin' when 'manager' then 'manager' else 'staff' end::user_role,'active',person<>'inactive',case when person='inactive' then 'inactive' else 'active' end::user_account_status) returning id into u;
  insert into rf values(person,u,null),(person||'_auth',a,null);
 end loop;
end $$;
create function pg_temp.rid(n text) returns uuid language sql as $$select id from rf where name=n$$;
create function pg_temp.ract(n text) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.rid(n||'_auth'),'role','authenticated')::text,true),set_config('request.jwt.claim.sub',pg_temp.rid(n||'_auth')::text,true),set_config('request.jwt.claim.role','authenticated',true)$$;
create function pg_temp.rsrv() returns void language sql as $$select set_config('request.jwt.claims','{"role":"service_role"}',true),set_config('request.jwt.claim.role','service_role',true)$$;
select pg_temp.ract('owner');
select throws_ok($$select recorder_issue_ticket(pg_temp.rid('device'),pg_temp.rid('request'),null,true,'pilot-v1')$$,'42501','recorder_pilot_disabled','pilot disabled by default');
insert into recorder_config(tenant_id,enabled,employee_ids,branch_ids) values(pg_temp.rid('tenant'),true,array[pg_temp.rid('owner')],array[pg_temp.rid('branch')]);
select throws_ok($$select recorder_issue_ticket(pg_temp.rid('device'),pg_temp.rid('request'),null,false,'pilot-v1')$$,'22023','recorder_consent_required','consent required');
insert into rf(name,body) values('start',recorder_issue_ticket(pg_temp.rid('device'),pg_temp.rid('request'),null,true,'pilot-v1'));
insert into rf(name,id) values('session',((select body from rf where name='start')->'session'->>'id')::uuid);
select is((recorder_issue_ticket(pg_temp.rid('device'),pg_temp.rid('request'),null,true,'pilot-v1')->'session'->>'id'),pg_temp.rid('session')::text,'start replay same durable session');
select throws_ok($$select recorder_issue_ticket(pg_temp.rid('device'),gen_random_uuid(),null,true,'pilot-v1')$$,'23505','recorder_device_busy','one open session per device');
select pg_temp.rsrv();
insert into rf(name,body) values('claims',recorder_ingest('redeem',jsonb_build_object('ticket',(select body->>'ticket' from rf where name='start')))->'session');
select throws_ok($$select recorder_ingest('redeem',jsonb_build_object('ticket',(select body->>'ticket' from rf where name='start')))$$,'42501','recorder_ticket_denied','single-use ticket');
update rf set body=body||jsonb_build_object('session_id',body->>'id') where name='claims';
create function pg_temp.rpayload() returns jsonb language sql as $$select body||coalesce((select jsonb_build_object('job_id',body->>'id','worker_id',body->>'worker_id','lease_token',body->>'lease_token') from rf where name='job'),'{}'::jsonb) from rf where name='claims'$$;
create function pg_temp.rchunk(seq integer,hash text default repeat('a',64)) returns jsonb language sql as $$select pg_temp.rpayload()||jsonb_build_object('sequence',seq,'sha256',hash,'byte_count',64000,'object_key','recordings/'||pg_temp.rid('tenant')||'/'||pg_temp.rid('branch')||'/'||pg_temp.rid('owner')||'/'||pg_temp.rid('device')||'/'||pg_temp.rid('session')||'/'||lpad(seq::text,8,'0')||'-'||hash||'.pcm')$$;
select throws_ok($$select recorder_ingest('chunk',pg_temp.rchunk(1))$$,'22023','recorder_chunk_order','gaps rejected');
select is((recorder_ingest('chunk',pg_temp.rchunk(0))->>'next_sequence')::integer,1,'durable chunk ACK');
select is((select health from recorder_devices where id=pg_temp.rid('device')),'recent_upload','receipt proves recent upload rather than microphone activity');
select is((recorder_ingest('chunk',pg_temp.rchunk(0))->>'next_sequence')::integer,1,'lost ACK replay deduplicates');
select throws_ok($$select recorder_ingest('chunk',pg_temp.rchunk(0,repeat('b',64)))$$,'23505','recorder_chunk_conflict','changed retry conflicts');
select throws_ok($$select recorder_ingest('chunk',pg_temp.rchunk(1)||jsonb_build_object('employee_id',gen_random_uuid()))$$,'42501','recorder_scope_denied','scope cannot be changed');
select throws_ok($$select recorder_ingest('commit',pg_temp.rpayload()||'{"last_sequence":1}')$$,'22023','recorder_commit_gap','unflushed last chunk cannot commit');
select is((recorder_ingest('chunk',pg_temp.rchunk(1)||'{"byte_count":2}')->>'next_sequence')::integer,2,'final partial PCM chunk accepted');
select is(recorder_ingest('commit',pg_temp.rpayload()||'{"last_sequence":1}')->'session'->>'status','processing','native commit seals and queues');
select is(recorder_ingest('commit',pg_temp.rpayload()||'{"last_sequence":1}')->'session'->>'status','processing','commit replay idempotent');
select is((select count(*)::integer from recorder_jobs where kind='final'),1,'one final durable job');
select pg_temp.ract('owner');
insert into rf(name,body) values('processing_ticket',recorder_issue_ticket(pg_temp.rid('device'),null,pg_temp.rid('session')));
select pg_temp.rsrv();
select is(recorder_ingest('redeem',jsonb_build_object('ticket',(select body->>'ticket' from rf where name='processing_ticket')))->'session'->>'status','processing','lost commit ACK permits fresh scoped lease');
select throws_ok($$select recorder_ingest('chunk',pg_temp.rchunk(2))$$,'22023','recorder_chunk_order','recovery lease cannot append sealed audio');
insert into rf(name,id) values('worker',gen_random_uuid()),('segment',gen_random_uuid());
insert into rf(name,body) values('job',recorder_ingest('claim_job',jsonb_build_object('worker_id',pg_temp.rid('worker')))->'job');
select is((select body->>'kind' from rf where name='job'),'provisional','live processing begins before final job');
select throws_ok($$select recorder_ingest('finish_job',jsonb_build_object('job_id',(select body->>'id' from rf where name='job'),'worker_id',pg_temp.rid('worker'),'lease_token',gen_random_uuid(),'success',true))$$,'42501','recorder_job_lease_denied','worker lease fencing');
select is(recorder_ingest('event',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'sequence',0,'revision',0,'text','Provisional','is_final',false,'started_ms',0,'ended_ms',1000))->>'accepted','true','provisional event persisted');
select is(recorder_ingest('event',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'sequence',0,'revision',1,'text','Final','is_final',true,'started_ms',0,'ended_ms',1000))->>'accepted','true','final reconciles provisional');
select is(recorder_ingest('event',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'sequence',0,'revision',2,'text','Stale provisional','is_final',false,'started_ms',0,'ended_ms',1000))->>'accepted','false','final cannot regress');
select recorder_ingest('finish_job',(select body from rf where name='job')||jsonb_build_object('job_id',(select body->>'id' from rf where name='job'),'success',true));
update rf set body=recorder_ingest('claim_job',jsonb_build_object('worker_id',pg_temp.rid('worker')))->'job' where name='job';
select recorder_ingest('finish_job',(select body from rf where name='job')||jsonb_build_object('job_id',(select body->>'id' from rf where name='job'),'success',true));
update rf set body=recorder_ingest('claim_job',jsonb_build_object('worker_id',pg_temp.rid('worker')))->'job' where name='job';
select is((select body->>'kind' from rf where name='job'),'final','final follows live jobs');
select throws_ok($$select recorder_ingest('finish_job',(select body from rf where name='job')||jsonb_build_object('job_id',(select body->>'id' from rf where name='job'),'success',true))$$,'22023','recorder_final_segments_missing','cannot Ready without canonical final coverage');
select is(recorder_ingest('event',pg_temp.rpayload()||jsonb_build_object('segment_id',gen_random_uuid(),'sequence',1,'revision',2,'text','','is_final',true,'started_ms',2000,'ended_ms',2001))->>'accepted','true','silence has explicit final segment');
select throws_ok($$select recorder_ingest('alert',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'code','critical_compliance','confidence',1,'evidence_text','Final','unambiguous',true))$$,'42501','recorder_coaching_denied','coaching disabled fails closed');
update recorder_config set coaching_enabled=true where tenant_id=pg_temp.rid('tenant');
select throws_ok($$select recorder_ingest('alert',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'code','critical_compliance','confidence',1,'evidence_text','Final','unambiguous',false))$$,'42501','recorder_coaching_denied','ambiguous evidence rejected');
select throws_ok($$select recorder_ingest('alert',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'code','critical_compliance','confidence',1,'evidence_text','different provider retry','unambiguous',true))$$,'42501','recorder_coaching_denied','signal must match canonical final text');
select throws_ok($$select recorder_ingest('alert',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'code','critical_compliance','confidence',0.5,'evidence_text','Final','unambiguous',true))$$,'42501','recorder_coaching_denied','low confidence signal denied by database');
select is(recorder_ingest('alert',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'code','critical_compliance','confidence',1,'evidence_text','Final','unambiguous',true))->>'accepted','true','final opted-in evidence produces alert');
select is(recorder_ingest('alert',pg_temp.rpayload()||jsonb_build_object('segment_id',pg_temp.rid('segment'),'code','critical_compliance','confidence',1,'evidence_text','Final','unambiguous',true))->>'accepted','false','duplicate critical alert suppressed');
select recorder_ingest('finish_job',(select body from rf where name='job')||jsonb_build_object('job_id',(select body->>'id' from rf where name='job'),'success',true));
select is((select status from recorder_sessions where id=pg_temp.rid('session')),'ready','successful final worker sets ready');

select pg_temp.ract('owner');
select is(jsonb_array_length(recorder_list_sessions()),1,'owner reads own session');
select pg_temp.ract('manager');
select is(jsonb_array_length(recorder_list_sessions()),1,'authorized branch manager reads');
select pg_temp.ract('ordinary');
select throws_ok($$select recorder_session_snapshot(pg_temp.rid('session'))$$,'42501','Section access denied','ordinary staff denied directly');
select pg_temp.ract('inactive');
select throws_ok($$select recorder_session_snapshot(pg_temp.rid('session'))$$,'42501','recorder_actor_denied','inactive actor denied');

select pg_temp.ract('owner');
select is(jsonb_array_length(recorder_linkable_walkins()),0,'no unverified customer choices');
select throws_ok($$select recorder_link_customer(pg_temp.rid('session'),'customer:unverified')$$,'0A000','recorder_crm_verification_unavailable','unverified CRM customer blocked');
select throws_ok($$select recorder_link_customer(pg_temp.rid('session'),'walkin:00000000-0000-0000-0000-000000000000')$$,'42501','recorder_link_denied','fabricated walk-in blocked');
insert into rf values('queue',gen_random_uuid(),null);
with task as (insert into task_instances(tenant_id,branch_id,task_type,title,planned_datetime,source,source_ref_id,created_by) values(pg_temp.rid('tenant'),pg_temp.rid('branch'),'delegation','Synthetic walk-in',now(),'crm_walkin',pg_temp.rid('queue'),pg_temp.rid('owner')) returning id)
insert into crm_sync.walkin_state(queue_id,snapshot_at,outcome,task_id) select pg_temp.rid('queue'),now(),'created',id from task;
select is(jsonb_array_length(recorder_linkable_walkins()),1,'only audited synced walk-in offered');
select is(recorder_link_customer(pg_temp.rid('session'),'walkin:'||pg_temp.rid('queue'))->>'customer_ref','walkin:'||pg_temp.rid('queue'),'verified walk-in link persisted');
select pg_temp.ract('manager');
update user_profiles set branch_id=pg_temp.rid('branch2') where id=pg_temp.rid('manager');
select throws_ok($$select recorder_session_snapshot(pg_temp.rid('session'))$$,'42501','recorder_session_denied','cross branch manager denied');
select is(jsonb_array_length(recorder_list_sessions()),0,'cross branch list empty');
select pg_temp.ract('owner');
set local role authenticated;
select is((select count(*)::integer from recorder_sessions),1,'RLS owner select allowed');
select throws_ok($$update recorder_sessions set status='ready'$$,'42501','permission denied for table recorder_sessions','client bypass write denied');
reset role;
select pg_temp.ract('ordinary');
set local role authenticated;
select is((select count(*)::integer from recorder_sessions),0,'RLS denied direct ordinary read');
reset role;

select pg_temp.ract('owner');
insert into rf(name,body) values('ready_ticket',recorder_issue_ticket(pg_temp.rid('device'),null,pg_temp.rid('session')));
select pg_temp.rsrv();
select is(recorder_ingest('redeem',jsonb_build_object('ticket',(select body->>'ticket' from rf where name='ready_ticket')))->'session'->>'status','ready','ready session permits final ACK recovery');
select is(recorder_ingest('commit',pg_temp.rpayload()||'{"last_sequence":1}')->'session'->>'status','ready','recovered final commit remains idempotent');
select pg_temp.ract('owner');
insert into rf(name,body) values('interrupted_start',recorder_issue_ticket(pg_temp.rid('device'),gen_random_uuid(),null,true,'pilot-v1'));
update recorder_sessions set status='needs_attention',error_reason='capture_interrupted',expires_at=now()-interval '1 second' where id=((select body from rf where name='interrupted_start')->'session'->>'id')::uuid;
select pg_temp.rsrv();
select recorder_ingest('reconcile','{}');
select ok((select capture_ended_at is not null from recorder_sessions where id=((select body from rf where name='interrupted_start')->'session'->>'id')::uuid),'retention releases interrupted device slot');
select pg_temp.ract('owner');
select lives_ok($$select recorder_issue_ticket(pg_temp.rid('device'),gen_random_uuid(),null,true,'pilot-v1')$$,'same device can start after interrupted retention expiry');

-- Ordinary staff capture is explicit permission + pilot configuration, never a role shortcut.
select pg_temp.ract('owner');
insert into user_permission_overrides(user_profile_id,tenant_id,permission_key,effect,updated_by) values
(pg_temp.rid('ordinary'),pg_temp.rid('tenant'),'module.sales_recording','grant',pg_temp.rid('owner')),
(pg_temp.rid('ordinary'),pg_temp.rid('tenant'),'recording.capture','grant',pg_temp.rid('owner'));
update recorder_config set employee_ids=array_append(employee_ids,pg_temp.rid('ordinary')) where tenant_id=pg_temp.rid('tenant');
select pg_temp.ract('ordinary');
select lives_ok($$select recorder_issue_ticket(gen_random_uuid(),gen_random_uuid(),null,true,'pilot-v1')$$,'explicitly granted active staff can capture in configured branch');
select is(jsonb_array_length(recorder_list_sessions()),1,'staff sees own session only');
select pg_temp.ract('owner');
select throws_ok($$do $test$ begin for i in 1..13 loop perform recorder_issue_ticket(pg_temp.rid('device'),null,pg_temp.rid('session')); end loop; end $test$;$$,'54000','recorder_ticket_rate_limit','ticket minting is bounded per employee');

select * from finish();
rollback;
